import React, { Component } from 'react';
import {
	CButton,
	CCard,
	CCardBody,
	CCardGroup,
	CCol,
	CContainer,
	CForm,
	CInput,
	CInputGroup,
	CInputGroupPrepend,
	CInputGroupText,
	CRow,
	CSelect,
	CTextarea
} from '@coreui/react';
import CIcon from '@coreui/icons-react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import { Loading } from '../Statuses/Statuses';
import { Logger, reloadPage } from '../../Utils/Utils';
import { requestHeaderGETWithAuth, requestHeaderPUTWithAuth } from '../../Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { BACKEND_TYPING_SPEED_SERVICE_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const initialState = {
	isLoaded: false,
	loadingModalVisible: false,
	loadingModalState: 0,
	failureModalVisible: false,
	sourceWebsites: [],
	sessionData: null
};

const FILE_NAME = "TypingSessionView.js";

class TypingSessionView extends Component {

	constructor(props) {
		super(props);
		this.state = JSON.parse(JSON.stringify(initialState));
	}

	resetStateToDefault() {
		this.setState(JSON.parse(JSON.stringify(initialState)));
	}

	componentDidMount() {
		document.title = "Satanlabs - View Typing Session";
		this.fetchSourceWebsites();
		this.fetchSessionData();
	}

	fetchSourceWebsites() {
		let API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/source/list?offset=0';
		const userData = getUserDataFromLocalStorage();

		fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({ failureModalVisible: true });
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({ failureModalVisible: true });
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_SOURCES", "result", result);
				if(result.code === 1001) {
					this.setState({ sourceWebsites: result.data });
					this.checkIfLoaded();
				} else {
					this.setState({ sourceWebsites: [] });
					this.checkIfLoaded();
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_SOURCES", "error", error);
				this.setState({ sourceWebsites: [] });
				this.checkIfLoaded();
			}
		);
	}

	fetchSessionData() {
		const sessionId = this.props.match.params.sessionId;
		let API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/' + sessionId;
		const userData = getUserDataFromLocalStorage();

		fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({ failureModalVisible: true });
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({ failureModalVisible: true });
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_SESSION", "result", result);
				if(result.code === 1001) {
					this.setState({ sessionData: result.data });
					this.checkIfLoaded();
				} else {
					this.setState({ failureModalVisible: true });
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_SESSION", "error", error);
				this.setState({ failureModalVisible: true });
			}
		);
	}

	checkIfLoaded() {
		if (this.state.sessionData && this.state.sourceWebsites !== null) {
			this.setState({ isLoaded: true });
		}
	}

	submitForm = (event) => {
		event.preventDefault();

		const sessionId = this.props.match.params.sessionId;

		let reqData = {
			id: parseInt(sessionId),
			wpm: parseInt(event.target.inputWpm.value),
			cpm: parseInt(event.target.inputCpm.value),
			accuracy: parseFloat(event.target.inputAccuracy.value),
			typingSourceWebsiteId: parseInt(event.target.inputSourceWebsite.value),
			extraNotes: event.target.inputExtraNotes.value
		};

		if(reqData.extraNotes === null || reqData.extraNotes.length < 1) {
			reqData.extraNotes = null;
		}

		this.setState({
			loadingModalVisible: true,
			loadingModalState: 0
		});

		let API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/update';
		const userData = getUserDataFromLocalStorage();
		fetch(API_URL, requestHeaderPUTWithAuth(JSON.stringify(reqData), userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_UPDATE", "result", result);
				if(result.code === 1001) {
					this.setState({
						loadingModalState: 1,
					});
					// Refresh data after update
					setTimeout(() => {
						this.setState({ loadingModalVisible: false, loadingModalState: 0 });
						this.fetchSessionData();
					}, 500);
				} else {
					this.setState({
						loadingModalVisible: false,
						loadingModalState: 0,
						failureModalVisible: true
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_UPDATE", "error", error);
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
		);
	}

	render() {
		Logger(FILE_NAME, "render", "", "this.state", this.state);
		const { sessionData } = this.state;

		return (
			this.state.isLoaded ?
			<div>
				<a href="#/typing-speed" style={{ textDecoration: 'none' }}>
					<CButton color="secondary" className="mb-3">← Back to Typing Sessions</CButton>
				</a>
				<CContainer>
					<CRow className="justify-content-center">
					<CCol md="8">
						<CCardGroup>
						<CCard className="p-4">
							<CCardBody>
							<CForm onSubmit={this.submitForm}>
								<h1>View / Edit Typing Session</h1>
								<p className="text-muted">ID: {sessionData.id} | Created: {sessionData.createdOn}</p>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilGlobeAlt" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CSelect
									id="inputSourceWebsite"
									required
									defaultValue={sessionData.typingSourceWebsiteId}
								>
									<option value="">-- Select Source Website --</option>
									{
										this.state.sourceWebsites.map(
											sw => <option key={"sw_option_" + sw.id} value={sw.id}>{sw.name}</option>
										)
									}
								</CSelect>
								</CInputGroup>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilSpeedometer" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CInput
									placeholder="WPM (Words Per Minute)"
									type="number"
									step="1"
									min="1"
									id="inputWpm"
									required
									defaultValue={sessionData.wpm}
								/>
								</CInputGroup>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilSpeedometer" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CInput
									placeholder="CPM (Characters Per Minute)"
									type="number"
									step="1"
									min="1"
									id="inputCpm"
									required
									defaultValue={sessionData.cpm}
								/>
								</CInputGroup>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilChart" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CInput
									placeholder="Accuracy (0-100)"
									type="number"
									step="any"
									min="0"
									max="100"
									id="inputAccuracy"
									required
									defaultValue={sessionData.accuracy}
								/>
								</CInputGroup>
								<CInputGroup className="mb-4">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilNotes" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CTextarea
									placeholder='Extra notes'
									id="inputExtraNotes"
									rows="3"
									defaultValue={sessionData.extraNotes || ''}
								/>
								</CInputGroup>
								<CRow>
									<CCol xs="6">
										<CButton color="primary" className="px-4" type='submit'>UPDATE</CButton>
									</CCol>
								</CRow>
							</CForm>
							</CCardBody>
						</CCard>
						</CCardGroup>
					</CCol>
					</CRow>
				</CContainer>

				<StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
				<FailureModal visible={this.state.failureModalVisible} />
			</div> : <Loading />
		);
	}
}

export default TypingSessionView;
